WITH review_input (
  professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
  attendance_required, grade_received, engagement_level, tags, created_at, import_key, course_ids
) AS (
  VALUES 
    (576::BIGINT, 'Literal de esos profes que se esfuerzan porque uno entienda, te ayuda demasiado, deja bastantes trabajos pero siempre es para ayudar a que uno pueda pasar. El curso es pesado pero si lo pueden llevar con Pedro lo pasan bien y él los salva cuando lo necesiten'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2026-06-13T00:00:00+00:00'::TIMESTAMPTZ, 'ee516f5cd98faf9d692df6e6d55b7c895fd45e5c96db0994439b939758746de1'::TEXT, ARRAY[2522]::BIGINT[]),
    (576::BIGINT, 'Es un profe muy comprensivo y flexible, le importan mucho los estudiantes. Aunque la primera parte del curso es muy teórica, el examen es práctico, pero si hace los ejercicios de las ppt le va a ir bien. Permite 1 hoja de apoyo en el examen y 1 página en quizzes, hace curva, pero de pocos puntos.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Pocos exámenes']::TEXT[], '2026-05-15T00:00:00+00:00'::TIMESTAMPTZ, '2d2779662391902b3615b4081d7188351bd5af33bd6a27cc52487c89c7824167'::TEXT, ARRAY[2522]::BIGINT[]),
    (576::BIGINT, 'Nunca evalúa, llegas a final de semestre sin saber tu nota para que se invente las evaluaciones, vas a ciegas todo el curso.'::TEXT, 8.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Muchos proyectos grupales']::TEXT[], '2025-06-28T00:00:00+00:00'::TIMESTAMPTZ, '17b6c83a5e9628bf030303e705ff38c38d4168ab4b7a9486343bcf4acdfcb67e'::TEXT, ARRAY[16]::BIGINT[]),
    (576::BIGINT, 'Hace clases sincrónicas X y la materia la deja en videos asincróncos. ¿¿¿¿¿??????.'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas']::TEXT[], '2024-12-22T00:00:00+00:00'::TIMESTAMPTZ, 'e894d97e2e2806cc7d05eed6b87c5c457f7745f83b7f2e5c02dc521330b53f73'::TEXT, ARRAY[2576]::BIGINT[]),
    (576::BIGINT, 'La parte difícil de este curso es saber que quiere el profe en la evaluación los aspectos son muy ambiguos y para peores grupos aleatorios eso fue lo feo del curso en verano.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Exámenes retadores']::TEXT[], '2024-01-27T00:00:00+00:00'::TIMESTAMPTZ, 'e6dac77f6a3bf6965fe18e23a14c6926bf204279a5c7aeca4448523c2652a24d'::TEXT, ARRAY[2589]::BIGINT[]),
    (576::BIGINT, 'Por Dios que curso, es la primera vez que da el curso y fue fatal corriendo con todo, horrible de la peor experiencia grupos aleatorios en cada trabaajo que dejaba. HORRIBLE'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Muchos proyectos grupales']::TEXT[], '2023-12-19T00:00:00+00:00'::TIMESTAMPTZ, 'a8065813a3201ddd9466caf8bd068375c6d714e51b1334f7b96791dc05dc2cb7'::TEXT, ARRAY[2577]::BIGINT[]),
    (576::BIGINT, 'Es un pésimo profesor, por más que lo intente no logra organizarse, teniendo que correr con las notas al final de semestre y manteniendo a la espera de resultados a los estudiantes para luego solo ponerle 100 a todo. Buena persona, pésimo profesor, no se organiza, no califica ni evalúa claramente.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Muchos proyectos grupales']::TEXT[], '2023-11-30T00:00:00+00:00'::TIMESTAMPTZ, 'aa6a1a8407520ee5517719a681e92e4cf1378b90e19317a0486a419a598a4adb'::TEXT, ARRAY[2577]::BIGINT[]),
    (576::BIGINT, 'Es un profe medio malo, se esfuerza por no serlo pero le male sal. Apenas si planifica la clase, se extiende y redunda demasiado. Subjetivo en las evaluaciones. No tuvo que haber aceptado los 2 cursos si la capacidad para revisar tantas evaluaciones no la iba a tener'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-11-11T00:00:00+00:00'::TIMESTAMPTZ, '1229dd0532785e5d684d4178a24ee7034fcbfb91f9ce84544970e9c39244af0d'::TEXT, ARRAY[16]::BIGINT[]),
    (576::BIGINT, 'Como profe todo bien pero me parece supercansado que los casos los haga con grupos aleatorios, porque hay gente que no hace nada y uno tiene que andar detrás. HORRIBLE en ese aspecto.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-11-01T00:00:00+00:00'::TIMESTAMPTZ, 'b5fd24b57e86a60c9aa603a1c3a2f83b9d92b1eeed6e5b6458bd1191d2b92d9e'::TEXT, ARRAY[16]::BIGINT[]),
    (576::BIGINT, 'El curso no es tan complicado pero el profesor a veces no da la ayuda necesaria para entender la materia, se debe de llevar muy al día.'::TEXT, 8.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Deja trabajos largos', 'Muchos proyectos grupales']::TEXT[], '2023-07-10T00:00:00+00:00'::TIMESTAMPTZ, 'd45cc417c1a9c0e070c826a3bb05f4f1aa5c9ff04e074f24703e7f898d71886d'::TEXT, ARRAY[2507]::BIGINT[]),
    (576::BIGINT, 'Deja muchos trabajos en grupo, los exámenes son difíciles pero suele poner ejercicios vistos en clase y deja muchas exposiciones.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Deja trabajos largos', 'Muchos proyectos grupales']::TEXT[], '2023-06-25T00:00:00+00:00'::TIMESTAMPTZ, 'c61d7a8809df63f14ad0630eda2adf8f4598ca905c4cf441c0bcbf18b48ae75b'::TEXT, ARRAY[2507]::BIGINT[]),
    (576::BIGINT, 'No es un mal profe, aunque hay que ser autodidactas ya que la materia la suele explicar por encima. Suele poner los ejercicios de la práctica en el propio examen, por lo cual es recomendable aunque sea pegarle una ojeada. Suele dejar trabajos en los cuales da puntos extra al que más le guste.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Deja trabajos largos', 'Muchos proyectos grupales']::TEXT[], '2023-06-25T00:00:00+00:00'::TIMESTAMPTZ, '187b0529cdc05eb8f1eb8ecad96e5b27c61d9d6b2b9b09f164706618ce12456c'::TEXT, ARRAY[2507]::BIGINT[]),
    (576::BIGINT, 'Uno de los peores cursos que he llevado, el profe dura las 2 horas de clase explicando algo que no sirve de nada y lo importante ni lo ve. Dice que ayuda al estudiantado cuando es mentira, el asistente era el que salvaba todas las tandas.'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Aspectos de calificación claros', 'Exámenes retadores']::TEXT[], '2023-06-24T00:00:00+00:00'::TIMESTAMPTZ, '10372595ed55b83ffab17284816b2a1cb237fc11f0be5dd22bfbdd7ef9816ddb'::TEXT, ARRAY[2507]::BIGINT[]),
    (576::BIGINT, 'El brodi es pura vida, sin embargo como profe es desordenado con las fechas de entregas, no se le entiende nada y califica duro, si no le da una respuesta esperese un 0 en la pregunta ya que no da absolutamente nada por procedimiento.'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Asistencia obligatoria', 'Exámenes retadores']::TEXT[], '2023-06-20T00:00:00+00:00'::TIMESTAMPTZ, 'bc8583a188435a4923ef1e033ade1a2c380fcf4717b7a80a3e7bb96ea9489390'::TEXT, ARRAY[2522]::BIGINT[]),
    (576::BIGINT, 'Buen profesor, pero a la hora de explicar es muy confuso, deja trabajos con una rúbrica confusa (a veces ni rúbrica pone) pero la materia se pasa, repase lo que "explica" practique bastantillo y se pasa, matricular con Pedro no es el fin del mundo'::TEXT, 6.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria', 'Exámenes retadores']::TEXT[], '2023-06-16T00:00:00+00:00'::TIMESTAMPTZ, '9ec846512fdabd854eb20640071a5736119952aa3703953759de34cef34a6d2a'::TEXT, ARRAY[2507]::BIGINT[]),
    (576::BIGINT, 'El profe es muy buena gente y probablemente buen profesional, pero es demasiado confuso; nunca quedó ningún tema claro pero él espera que uno los maneje súper bien. Los exámenes son complicados pero el forro que deja usar ayuda bastante. Importante hacer todos los trabajos, no cuesta tanto pasar.'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-06-16T00:00:00+00:00'::TIMESTAMPTZ, '1f45748ea7487f05f30e974c53255e6c476cccb537cc2ab52d1cdce7b7b81a3f'::TEXT, ARRAY[2522]::BIGINT[]),
    (576::BIGINT, 'Es relativamente buena persona, pero pésimo profesor, se enreda al explicar, tarda muchísimo en entregar las notas de cualquier evaluación, exige mucho como si fuera buen profesor, deja trabajos largos cuyas instrucciones no se entienden, pretende que adivinemos que es lo que él quiere.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Asistencia obligatoria', 'Deja trabajos largos']::TEXT[], '2023-06-15T00:00:00+00:00'::TIMESTAMPTZ, 'fe1f3aecc3980a771062281229cac93bd2f19c30ff3bc783e1243eff60065c41'::TEXT, ARRAY[2522]::BIGINT[]),
    (576::BIGINT, '4 exámenes durísimos en donde hay que estudiar bien para pasar, hay que hacer todas las tareas morales si querés pasar, el es buena nota pero duro.'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchos exámenes']::TEXT[], '2023-06-12T00:00:00+00:00'::TIMESTAMPTZ, 'cbb3ee581bb8786d726e25b53f96bc2dfd1e82c9ff6eabb4c16a6e58c99b1b2a'::TEXT, ARRAY[2507]::BIGINT[]),
    (576::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2023-04-06T00:00:00+00:00'::TIMESTAMPTZ, 'c9dfad1f9f240e46fdfab958e3fa23c1a5d134be84ca44cb5aa66d7414de1911'::TEXT, ARRAY[2507]::BIGINT[]),
    (576::BIGINT, 'Una teja de persona, a veces se confunde, pero téngale paciencia y no tenga miedo a preguntar.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Inspirador', 'Da crédito extra']::TEXT[], '2022-06-21T00:00:00+00:00'::TIMESTAMPTZ, 'daaf842227f5d4e02618b60fdb243a590bd9e1f27e4f00c1bff026a0b409295b'::TEXT, ARRAY[2522]::BIGINT[]),
    (576::BIGINT, 'El profe es buena nota y lo va ayudar cuando usted lo necesite, a veces se confunde en la explicación pero general es fácil pasar con él.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Da crédito extra', 'Tomaría su clase nuevamente']::TEXT[], '2022-06-09T00:00:00+00:00'::TIMESTAMPTZ, '343639d7958f540c49d4ec058c87b499ed9f8a6430a6ddb88f3b11e98f453838'::TEXT, ARRAY[2522]::BIGINT[]),
    (576::BIGINT, 'El profe sabe mucho, pero no explica muy bien, las evaluaciones son duras, muchas practicas no tan teoricas, da muy poco tiempo para hacerlas, pero si necesitas ayuda el te explica, saca todas las consultas que tenemos, etc. (ojo esto es en virtual)'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Brinda apoyo', 'Exámenes retadores']::TEXT[], '2022-06-02T00:00:00+00:00'::TIMESTAMPTZ, '06307e87cf51fdfd5ec4894cc80fa424fa8dca753246b9d8d4ab7628c796e26b'::TEXT, ARRAY[2522]::BIGINT[]),
    (576::BIGINT, 'PÉSIMO Él le va a exigir como si fuera un buen profesor, pero no es consiente de que NO sabe enseñar, se enreda solo, no da calificaciones a tiempo, deja laboratorios y uno los hace a ciegas porque: 1) No revisa los anteriores laboratorios. 2) NO explica la materia antes de dejar el laboratorio.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Deja trabajos largos']::TEXT[], '2021-10-03T00:00:00+00:00'::TIMESTAMPTZ, '7ee87ed959c26faf2aaa54648de31531b4d3f6aea7ccc0f0561d8b454f3ba915'::TEXT, ARRAY[2576]::BIGINT[]),
    (576::BIGINT, 'Es un buen profe. A veces la materia no queda muy clara, pero si uno de verdad se sienta a estudiar llega a entender bastante. Como área de mejora, serian las explicaciones en clase ya que no son muy buenas'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Muchos proyectos grupales', 'Tomaría su clase nuevamente']::TEXT[], '2021-07-22T00:00:00+00:00'::TIMESTAMPTZ, '1acd945dab2f2d633c079cdcf6a74ce56f003b96d66edbcf822492275edd2eb6'::TEXT, ARRAY[2522]::BIGINT[]),
    (576::BIGINT, 'Este mae no sabe nada del curso, esta super perdido, sus exámenes/quices son rarismos porque la clase es teorica y esas evaluaciones son completamente prácticas, entonces fue horrible, pase un mal momento con él, sus clases son un asco sinceramente'::TEXT, 8.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2021-07-10T00:00:00+00:00'::TIMESTAMPTZ, '06f85c4d9c39872ac50e6eef0fd1e68583f4829b5547d4df7c4256bac1279e54'::TEXT, ARRAY[2522]::BIGINT[]),
    (576::BIGINT, 'Termine sabiendo yo más de la materia que el profe, no es su área, los exámenes son un enredo y tiene que dar muchísimos puntos, en resumen aprendí pero no me acuerdo de nada. No es claro. Pasar fácil depende de usted, haga todos los trabajos y pasa bien.'::TEXT, 10.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Muchos exámenes', 'Exámenes retadores']::TEXT[], '2021-06-30T00:00:00+00:00'::TIMESTAMPTZ, '6aaaba9e23271e5218f25af66b0fc190cb1e5dbc2ea034e858d1307f0565a84c'::TEXT, ARRAY[2522]::BIGINT[]),
    (576::BIGINT, '¿ Es Pedro un buen profe? Le devuelvo la pregunta. Podríamos suponer que sí, pero hay momentos en los que no del todo, entonces depende.'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-06-30T00:00:00+00:00'::TIMESTAMPTZ, '3218886ab260a32d4ae95d8006a932fc32ddbf316a401db399b662b0d02aeabb'::TEXT, ARRAY[2522]::BIGINT[]),
    (576::BIGINT, 'Pésimo. No domina la materia. Los exámenes son un DESASTRE. Las clases son aburridas y no se aprende nada. Al final uno pasa porque leyó uno solo pero él como tal es malísimo. No lleven con él, a menos que quieran pasar sin aprender nada.'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura']::TEXT[], '2021-06-26T00:00:00+00:00'::TIMESTAMPTZ, 'e5ae8ddaaea80f221a3638ad5f933322b4b5718c2d5d66eda74d7b466a2657f9'::TEXT, ARRAY[2522]::BIGINT[]),
    (576::BIGINT, 'Si lo que quiere es pasar un curso con relativa facilidad y sin aprender mucho, lleve el curso con él. No se nota que tenga un dominio real del tema. Sus presentaciones se pueden encontrar exactamente iguales en plataformas como Coursera o CourseHero. Comete muchos errores en los exámenes'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Da crédito extra', 'Muchos proyectos grupales']::TEXT[], '2021-06-11T00:00:00+00:00'::TIMESTAMPTZ, '438bb88dfd17c1d44e8431cf95729f20a0cb259a759cde71f6646ed1059a0a08'::TEXT, ARRAY[2522]::BIGINT[]),
    (576::BIGINT, 'Profe, por favor replanteé su metodología de enseñanza, necesita ser mas eficiente y claro al momento de dar la clase. Haga exámenes con menos errores que siempre siempre hay. Usted arregla esos 3 aspectos y listo. Se lo digo así en buen plan'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Exámenes retadores']::TEXT[], '2021-03-26T00:00:00+00:00'::TIMESTAMPTZ, '8d5d41cef343d9dc183cdfe463612e574805cba03145048643357095f08f8d2f'::TEXT, ARRAY[2522]::BIGINT[]),
    (576::BIGINT, 'El profe se pierde explicando y pierde al estudiante. Además, pierde mucho el tiempo haciendo que los estudiantes contesten una pregunta cada diapositiva. No es eficaz y por querer tener todo súper ordenado termina provocando un desastre. Los exámenes son muy extraños y siempre terminan en quejas.'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria']::TEXT[], '2020-08-25T00:00:00+00:00'::TIMESTAMPTZ, '9db972749fd865c18f05bfd16bafb4d7652edc87d11a83046b8cd39d00fffe9d'::TEXT, ARRAY[2507]::BIGINT[]),
    (576::BIGINT, 'Sus clases son sumamente cansadas, no domina bien los temas, pierde al estudiante cuando explica, hace muchas preguntas y cuesta mucho contactarlo cuando se tiene una duda. Las preguntas del examen son super ambiguas.'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'La participación importa', 'Clases largas']::TEXT[], '2020-08-24T00:00:00+00:00'::TIMESTAMPTZ, 'c37a8ff8d26e692024877cdd48f211a2c2b69f01f8322e22a0de24a69d2d83f5'::TEXT, ARRAY[2522]::BIGINT[]),
    (576::BIGINT, 'Él quiere ser cómico y ser "un profe cool" pero termina siendo lo opuesto. Súper desordenado, piensa que con leer un libro ya está. Si quiere aprender, no matricule con él.'::TEXT, 8.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Asistencia obligatoria']::TEXT[], '2020-08-24T00:00:00+00:00'::TIMESTAMPTZ, 'ca042d79ac96fc902e5e73e568246a07121f42a2d3cb31c270a03efb0edde561'::TEXT, ARRAY[2591]::BIGINT[]),
    (576::BIGINT, 'Es un muy buen profe, ayuda mucho cuando uno tiene una duda y siempre esta dispuesto a ayudar con los trabajos. Lo recomiendo mucho, un profesor muy accesible.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-24T00:00:00+00:00'::TIMESTAMPTZ, 'c521ab904b660cccc30379297d83a98dea9d3ea905eccbed1ce143abd510b956'::TEXT, ARRAY[2507]::BIGINT[]),
    (576::BIGINT, 'Es bastante accesible al momento de calificar. Le gusta hacer trabajos grupales y es importante la participación en clase.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Requiere mucha lectura']::TEXT[], '2020-08-19T00:00:00+00:00'::TIMESTAMPTZ, 'a9e36e24034d7510317bf2673edff59715dec252aefdf3b2c85af9f6609004b0'::TEXT, ARRAY[3093]::BIGINT[]),
    (576::BIGINT, 'Las clases son un poco aburridas y en algunos aspectos de costos no tiene mucho conocimiento, sin embargo enfoca el desarrollo de la clase a costos en TI lo cual genera valor para la carrera'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Clases largas']::TEXT[], '2020-08-16T00:00:00+00:00'::TIMESTAMPTZ, '345e4b91de988c943a6776ff4da46709090926cfccc86beb7eaf211d1e289bc4'::TEXT, ARRAY[2522]::BIGINT[]),
    (576::BIGINT, 'Fue un desastre ????. Tanto presencial como virtual. No explica bien. Va SÚPER lento. Y Dios guarde, le haga una pregunta uno, porque no sabe responder y se enreda demasiado. No da seguridad para nada y parece que no conoce de la materia.'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-13T00:00:00+00:00'::TIMESTAMPTZ, '9c583c0918767437c5d0b568dd6f50d7e8bfce01f9c54686a6a7b62c15a35aad'::TEXT, ARRAY[2507]::BIGINT[]),
    (576::BIGINT, 'Sus clases son lo opuesto a las de Mario, aquí es pura teoría. Es un poco desordenado en cuanto a dar explicaciones, y se nota más en la virtualidad. Normalmente las instrucciones que da son confusas y los con trabajos que deja no se aprende nada'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'La participación importa']::TEXT[], '2020-08-11T00:00:00+00:00'::TIMESTAMPTZ, '52d174bcb6f3143b511fab8829454856f1a59dc1f6f8704bf84951091ed8a870'::TEXT, ARRAY[2522]::BIGINT[]),
    (576::BIGINT, 'El profe es buena nota, lo que pasa es que no se aclara en las ideas, se desvía mucho del tema principal, lo que puede llegar a confundir. Tarda mucho en subir las notas a TD.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2020-08-05T00:00:00+00:00'::TIMESTAMPTZ, 'd1ed1241a4f36bf9b930823e8bb12bdf3034542dffbe222289927850a4c148bb'::TEXT, ARRAY[2522]::BIGINT[]),
    (576::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas', 'Deja trabajos largos']::TEXT[], '2020-08-04T00:00:00+00:00'::TIMESTAMPTZ, '709883534b90c3824a43f455a4f75edcd0c0568c479766e579a87da4ac655ebe'::TEXT, ARRAY[2507]::BIGINT[]),
    (576::BIGINT, 'Cualquier pregunta que usted le haga le va a responder confuso y al final va a tener que suponer todo.'::TEXT, 6.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Asistencia obligatoria']::TEXT[], '2020-07-22T00:00:00+00:00'::TIMESTAMPTZ, '222771fa57af427511571422d8a77e6abcf5e2e3313856dc086a33a765519246'::TEXT, ARRAY[2507]::BIGINT[]),
    (576::BIGINT, 'Matricule con Mario antes que con Pedro'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-06-24T00:00:00+00:00'::TIMESTAMPTZ, '34049454f0e618203735ed4f796cf3d1c4de573ff18e59380e5c6b864bf3922a'::TEXT, ARRAY[2522]::BIGINT[]),
    (576::BIGINT, 'no es mal profe, pero exige demasiado de uno explica la parte fácil y uno tiene que aprender por su cuenta la difícil. Cae bien pero no sabe tanto de conta, como para dar clases de conta o simplemente no sabe dar la clase.'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Requiere mucha lectura']::TEXT[], '2020-06-08T00:00:00+00:00'::TIMESTAMPTZ, 'b5062bff1cfd0dd65cc726f070c8f8a189ce41b41b00d04e06c67f0baa5361be'::TEXT, ARRAY[2507]::BIGINT[]),
    (576::BIGINT, 'No explica, solo le hace preguntas a los estudiantes acerca de la materia que tienen que aprender por su cuenta.'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria']::TEXT[], '2020-05-20T00:00:00+00:00'::TIMESTAMPTZ, 'a3ca9e829c210f761f1a68457ee9a19e9f0d90de766e512fd9140d63ee502a45'::TEXT, ARRAY[2507]::BIGINT[]),
    (576::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'La participación importa', 'Asistencia obligatoria']::TEXT[], '2020-05-20T00:00:00+00:00'::TIMESTAMPTZ, '95222529507763ef730980e8231b25fd3b9fe3f9de3a3542adee71b834456d1c'::TEXT, ARRAY[2507]::BIGINT[]),
    (576::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Inspirador', 'Clases excelentes']::TEXT[], '2020-02-07T00:00:00+00:00'::TIMESTAMPTZ, '3746a6b3bade34ee4e95212557caf6e9f8975445736274d729abf9c9eab242a7'::TEXT, ARRAY[2507]::BIGINT[]),
    (576::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Asistencia obligatoria', 'Exámenes retadores']::TEXT[], '2019-11-28T00:00:00+00:00'::TIMESTAMPTZ, '937fafba643f74e7cf79f9060411a5f474f2bdfa86ab962bd8a12dcac839f4e0'::TEXT, ARRAY[2507]::BIGINT[]),
    (576::BIGINT, 'Califica duro, muy cómico, muchas tareas, inspiracional ya que es egresado de nuestra carrera (ATI), tomaría su clase otra vez y está muy guapo.'::TEXT, 2.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2018-05-10T00:00:00+00:00'::TIMESTAMPTZ, 'afec586faecd146e26596904acce41322e45cc11b8449f4a8b69525a36a82fec'::TEXT, ARRAY[2522]::BIGINT[]),
    (576::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Respetado por los estudiantes', 'Aspectos de calificación claros']::TEXT[], '2018-01-30T00:00:00+00:00'::TIMESTAMPTZ, '26e1751936298b827c6c75e2a665f66fc135d66839d81eb20f8f8b49f6ad2db7'::TEXT, ARRAY[2522]::BIGINT[]),
    (576::BIGINT, 'Es egresado de ATI, sabe mucho de algoritmos y explica la materia como debe ser. Pero como profesor es muy bueno aunque va ganando experiencia. Si tiene dudas es mejor que vaya a consultas explica mucho más mejor que la clase. Pero sobre todo buen profe y sabe mucho.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2017-11-27T00:00:00+00:00'::TIMESTAMPTZ, 'a0a392b790eb0b9bda9b841d2feb4fd04985b0cac6a929dcf88687f5ad40a45e'::TEXT, ARRAY[2510, 2512]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
